-- Migration 0002: seed 16 Cores + global admin settings
-- SHA-256('PEOPLE-05152005') = computed below at insert time via pgcrypto digest()
create extension if not exists "pgcrypto";

on conflict (id) do update set
  name = excluded.name, tagline = excluded.tagline, description = excluded.description,
  rules = excluded.rules, accent_color = excluded.accent_color, gradient = excluded.gradient,
  layout = excluded.layout, icon_name = excluded.icon_name;

-- Global admin settings (hash of PEOPLE-05152005 installed by app if missing)
values ('global', encode(digest('PEOPLE-05152005','sha256'),'hex'), '{}')
on conflict (id) do nothing;
